        const ids = (await r.json()).slice(0, lim);
        const titles = [];
        for (const id of ids) { const rr = await fetch("https://hacker-news.firebaseio.com/v0/item/" + id + ".json"); const it = await rr.json(); if (it && it.title) titles.push(it.title); }
        return json({ content: [{ type: "text", text: "HN top " + lim + ":\n- " + titles.join("\n- ") }] });
