        const q = encodeURIComponent(args.q || "");
        const r = await fetch("https://api.duckduckgo.com/?q=" + q + "&format=json&no_html=1");
        const j = await r.json();
        const top = (j.RelatedTopics || []).filter(x => x.Text).slice(0, 5).map(x => "- " + x.Text).join("\n");
        return json({ content: [{ type: "text", text: "Results for '" + (args.q || "") + "':\n" + (top || "no results") }] });
